// ══ core/engine/minifloat.js ══
// ThreeFiveMiniUfloat — port of tsvm_core/src/net/torvald/tsvm/ThreeFiveMinifloat.kt.
// 3.5 unsigned minifloat (3-bit exponent + 5-bit mantissa) scaled so the smallest
// non-zero step is 1/256 s ≈ 3.91 ms and the max is 15.75 s. Used for Taud
// envelope point offsets.
//
// The LUT is generated by the minifloat formula (e = i>>5, m = i&31;
// denormal e=0 → m/256, else (32+m)·2^(e−1)/256) — values are exact binary
// fractions, so this reproduces the Kotlin float LUT bit-exactly.

const MINIFLOAT_LUT = new Float32Array(256);
for (let i = 0; i < 256; i++) {
  const e = i >> 5;
  const m = i & 31;
  MINIFLOAT_LUT[i] = e === 0 ? m / 256 : ((32 + m) * 2 ** (e - 1)) / 256;
}

function minifloatToDouble(index) {
  return MINIFLOAT_LUT[index & 0xff];
}

// fromFloatToIndex (ThreeFiveMinifloat.kt:24-27): binary-search the interval,
// then "round to nearest even" — if the lower bound index is even take it,
// else take the upper bound. Ported verbatim, quirk included.
function minifloatFromDouble(fval) {
  let low = 0;
  let high = MINIFLOAT_LUT.length - 1;
  let llim, hlim;
  for (;;) {
    if (low > high) {
      llim = Math.max(high, 0);
      hlim = Math.min(low, MINIFLOAT_LUT.length - 1);
      break;
    }
    const mid = (low + high) >>> 1;
    const midVal = MINIFLOAT_LUT[mid];
    if (fval < midVal) high = mid - 1;
    else if (fval > midVal) low = mid + 1;
    else { llim = mid; hlim = mid; break; }
  }
  return llim % 2 === 0 ? llim : hlim;
}

// ══ core/engine/rng.js ══
// Randomness seams for the Taud engine. No engine file may call Math.random
// directly — everything routes through here so tests (the golden gate) can seed it.
//
// Two independent streams, mirroring AudioAdapter.kt:
//  - xorshift32: the noise-shaped dither PRNG in pcm32fToPcm8 (deterministic,
//    seeded constant per adapter instance — AudioAdapter.kt:1199-1214)
//  - random(): Math.random uses — vol/pan swing at trigger (2593-2597) and the
//    random LFO waveform 3 (1432). Musically intended nondeterminism in
//    production; injectable for tests.

function makeXorshift32(seed = 0x9e3779b9) {
  let x = seed >>> 0;
  return function xorshift32() {
    x ^= (x << 13) >>> 0;
    x ^= x >>> 17;
    x ^= (x << 5) >>> 0;
    x = x >>> 0;
    return x;
  };
}

// Injectable uniform [0,1) source.
let _random = Math.random;

function random() {
  return _random();
}

/** Replace the uniform source (pass null to restore Math.random). */
function setRandomSource(fn) {
  _random = fn ?? Math.random;
}

/** Simple seedable mulberry32 for tests. Its `state()` is where the stream
 *  stands — what a WebAssembly engine continues it from (engineSeed). */
function makeSeededRandom(seed = 1) {
  let a = seed >>> 0;
  function mulberry32() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }
  mulberry32.state = () => a;
  return mulberry32;
}

/**
 * The 32-bit state a WebAssembly engine starts its own generator from. The
 * module imports nothing, so it cannot call the source installed here; it runs
 * the same mulberry32 inside instead. With a makeSeededRandom source installed
 * the engine continues THAT stream from where it stands, so a seeded render is
 * the same render in either engine; otherwise the seed is one draw from the
 * source in force (Math.random in production).
 */
function engineSeed() {
  if (typeof _random.state === "function") return _random.state() >>> 0;
  return Math.floor(_random() * 4294967296) >>> 0;
}

// ══ core/engine/dither.js ══
// The two quantisers a float mix is delivered through.
//
// pcm32fToPcm8 is the DEVICE's: the noise-shaped 8-bit dither the Taud adapter
// plays through (and a GRITTY WAV export is written with). It is here rather
// than in the mixer so that what only needs the dither — the WAV encoder, the
// player library — does not carry a mixer along; the C engine has its twin
// (te_dither_u8).
//
// ditherS16 is the 16-bit quantiser a CLEAN stereo WAV export writes.
//
// Plain TPDF dither of one LSB peak, no noise shaping, off its own xorshift32
// stream at the adapter's seed — so an export is the same file every time, and
// the master meter's 16-bit bit-usage census (loudness.js), which runs the
// same stream over the same bus from the start of an offline analysis, counts
// exactly the codes the file holds.
//
// Not part of the device: nothing the engine plays goes through here, which is
// why it owes TSVM nothing. libtaudplay carries the same arithmetic
// (taud_encode_wav), operand order included.


/** A fresh dither stream — the generator ditherS16 draws from. */
function makeDither16() {
  return makeXorshift32();
}

/**
 * One float sample (nominal ±1) → a signed 16-bit code: clamp, scale by 32767
 * (the undithered writer's scale), add a triangular −1…+1 LSB, round. Two draws
 * per sample, the first one positive.
 */
function ditherS16(next, x) {
  const v = x < -1 ? -1 : x > 1 ? 1 : x;
  const a = next() & 0xffffff;
  const b = next() & 0xffffff;
  const q = Math.round(v * 32767 + (a - b) / 16777216);
  return q < -32768 ? -32768 : q > 32767 ? 32767 : q;
}

const ditherFround = Math.fround;

/** urand: (xorshift32() & 0xFFFFFF) / 16777216 — exact in Float32. */
function urand(eng) {
  return (eng.xorshift32() & 0xffffff) / 16777216.0;
}

/** TPDF noise in [-1, +1) — difference of two urands, exact in Float32. */
function tpdf1(eng) {
  return urand(eng) - urand(eng);
}

/**
 * Noise-shaped dither 32f → interleaved U8, writing into out (length ≥ 2·sampleCount).
 * State: eng.ditherError = Float32Array(4) [L0, L1, R0, R1].
 */
function pcm32fToPcm8(eng, fleft, fright, sampleCount, out) {
  const b1 = 1.5;
  const b2 = -0.75;
  const scale = 127.5;
  const bias = 128;
  const ditherScale = 0.2; // ditherFround(0.2) applied at the multiply below
  const err = eng.ditherError;

  for (let i = 0; i < sampleCount; i++) {
    // --- LEFT channel ---
    const feedbackL = ditherFround(ditherFround(b1 * err[0]) + ditherFround(b2 * err[1]));
    const ditherL = ditherFround(ditherFround(ditherScale) * tpdf1(eng));
    let shapedL = ditherFround(ditherFround(fleft[i] + feedbackL) + ditherFround(ditherL / scale));
    shapedL = shapedL < -1.0 ? -1.0 : shapedL > 1.0 ? 1.0 : shapedL;

    let qL = Math.round(ditherFround(shapedL * scale));
    qL = qL < -128 ? -128 : qL > 127 ? 127 : qL;
    out[i * 2] = (qL + bias) & 0xff;

    const qerrL = ditherFround(shapedL - ditherFround(qL / scale));
    err[1] = err[0];
    err[0] = qerrL;

    // --- RIGHT channel ---
    const feedbackR = ditherFround(ditherFround(b1 * err[2]) + ditherFround(b2 * err[3]));
    const ditherR = ditherFround(ditherFround(ditherScale) * tpdf1(eng));
    let shapedR = ditherFround(ditherFround(fright[i] + feedbackR) + ditherFround(ditherR / scale));
    shapedR = shapedR < -1.0 ? -1.0 : shapedR > 1.0 ? 1.0 : shapedR;

    let qR = Math.round(ditherFround(shapedR * scale));
    qR = qR < -128 ? -128 : qR > 127 ? 127 : qR;
    out[i * 2 + 1] = (qR + bias) & 0xff;

    const qerrR = ditherFround(shapedR - ditherFround(qR / scale));
    err[3] = err[2];
    err[2] = qerrR;
  }
}

// ══ core/engine/tables.js ══
// Lookup tables + pitch math — port of AudioAdapter.kt companion object tables
// (149-340), MOD_SIN_TABLE / FINETUNE_OFFSET (1406-1422), META_MIX_GAIN (1480),
// EffectOp (1438), lfoSample (1426), pitch conversions (1632-1690).



// ── The sinc kernel (engine spec §8.3) ──
// SINC_TABLE[i] is the Hann-windowed sinc at i ÷ SINC_PRECISION samples from
// the centre, and 0 at the last entry, where the window ends.
const SINC_TABLE_SIZE = SINC_PRECISION * SINC_WIDTH;
const SINC_TABLE = (() => {
  const n = SINC_TABLE_SIZE;
  const out = new Float64Array(n + 1);
  const winFreq = Math.PI / SINC_WIDTH / SINC_PRECISION;
  out[0] = 1.0;
  for (let i = 1; i < n; i++) {
    const t = (i * Math.PI) / SINC_PRECISION;
    const win = 0.5 + 0.5 * Math.cos(winFreq * i);
    out[i] = (Math.sin(t) / t) * win;
  }
  return out;
})();

// The same numbers laid out for the sampler: row p holds the six coefficients
// of sub-sample phase p, for the taps −2…+3 (tap j of phase p sits
// |j·SINC_PRECISION − p| table steps from the centre).
const SINC_TAPS = SINC_WIDTH * 2;
const SINC_PHASE = (() => {
  const out = new Float64Array(SINC_PRECISION * SINC_TAPS);
  for (let p = 0; p < SINC_PRECISION; p++) {
    for (let j = 1 - SINC_WIDTH; j <= SINC_WIDTH; j++) {
      out[p * SINC_TAPS + (j + SINC_WIDTH - 1)] = SINC_TABLE[Math.abs(j * SINC_PRECISION - p)];
    }
  }
  return out;
})();

