      // without vibrato, as the reference core has it.
      st.hhPhase = (st.hhPhase + st.hhInc) >>> 0;
      st.tcPhase = (st.tcPhase + st.tcInc) >>> 0;
      const hp = (st.hhPhase >>> 10) & 0x3ff;
      const tp = (st.tcPhase >>> 10) & 0x3ff;
